entries[1230698] = { ["name"] = "Sande von K'aresh", ["text"] = "Unbegrenzte Reichweite\nSofort\nWenn Brann ' Sammelwerkzeuge ' einsetzt, beginnen Sande um die Gruppenmitglieder zu wirbeln, gewähren bis zu 10-mal 6% kritischen Trefferwert und verlangsamen Gegner in der Nähe um 6%.\n\nEin kritischer Treffer erschafft 6 Sek. lang einen Sandteufel am Ort des Ziels, der Gegner periodisch in sein Zentrum zieht. Kann nur alle 45 Sek. auftreten.\n\nSammelwerkzeuge\nBrann setzt seine Sammelwerkzeuge ein, um Spielercharakteren zu helfen, zusätzliches Gold, Erz, Leder, zusätzliche Kräuter, Fische und Schätze zu finden." }
