entries[1233105] = { ["name"] = "Dunkle Rückstände", ["text"] = "Unbegrenzte Reichweite\nSofort\nDie stellaren Überreste brennen und verursachen 5 Sek. lang alle 1 Sek. 2023752 kosmischen Schaden. Dieser Effekt ist stapelbar." }
entries[1233109] = { ["name"] = "Hatarang", ["text"] = "100 Meter Reichweite\nSofort\nCa. 2 Procs pro Minute\nBrann hat eine Chance, zufällig ausgewählte Hüte hervorzuziehen und sie auf seine Gegner zu werfen, wodurch er mäßigen Schaden verursacht und 1 Schwächungseffekt auf 2 Ziele anwendet.\n\nMögliche Schwächungseffekte sind eine Erhöhung des erlittenen Schadens um 20%, eine Verringerung des verursachten Schadens um 20% sowie eine Verringerung des Angriffs- und Zaubertempos um 20%.\n(20s Abklingzeit)" }
entries[1233110] = { ["name"] = "Läuternder Blitzschlag", ["text"] = "300 Meter Reichweite\nSofort\nDie Plexuswache kanalisiert durchgehend arkane Blitze durch sein Chassis, die allen Spielercharakteren mit jedem Wirken 386480 Arkanschaden zufügen. Jedes Wirken stärkt das Chassis, wodurch der Schaden nachfolgender Einsätze um 25% erhöht wird. Dieser Effekt ist stapelbar." }
entries[1233111] = { ["name"] = "Hatarang", ["text"] = "Unbegrenzte Reichweite\nSofort\nBrann hat eine Chance, zufällig ausgewählte Hüte hervorzuziehen und sie auf seine Gegner zu werfen, wodurch er mäßigen Schaden verursacht und 1 Schwächungseffekt auf 2 Ziele anwendet.\n\nMögliche Schwächungseffekte sind eine Erhöhung des erlittenen Schadens um 20 %, eine Verringerung des verursachten Schadens um 20 % sowie eine Verringerung des Angriffs- und Zaubertempos um 20 %." }
