entries[1233491] = { ["name"] = "Erobern", ["text"] = "Unbegrenzte Reichweite\nKanalisiert (Wirken in 5 sek.)\nSalhadaar schmettert auf sein aktuelles Ziel ein, verursacht 101187582 körperlichen Schaden und zusätzlich 75890687 Schattenschaden, der auf alle Spielercharaktere innerhalb von 8 Metern aufgeteilt wird, um sie in die Luft zu schleudern.\n\nGetroffene Spielercharaktere verlieren einen Stapel von ' Eidgebunden '. Erhöht den durch ' Erobern ' erlittenen Schaden 20 Sek. lang um 500%." }
entries[1233492] = { ["name"] = "Bezwingen", ["text"] = "Unbegrenzte Reichweite\nKanalisiert (Wirken in 3 sek.)\nSalhadaar spaltet sein aktuelles Ziel und fügt allen Spielercharakteren vor sich 22486129 körperlichen Schaden und zusätzlich 35415654 Schattenschaden zu, wobei diese weggestoßen werden.\n\nErhöht den durch ' Bezwingen ' erlittenen Schaden 20 Sek. lang um 500%." }
