entries[1233511] = { ["name"] = "Umbralk'arroc", ["text"] = "Wirken in 1.5 sek.\nBeschwört dieses Reittier oder gibt es wieder frei.\n\"Ein wilder K'arroc, der besonders gut darauf ausgelegt ist, das ewigwährende Zwielicht von K'aresh zu durchstreifen.\"\nErfolg:\nRuhm des Omegaschlachtzüglers\nKategorie:\nDungeons & Schlachtzüge" }
entries[1233515] = { ["name"] = "Dateninformationssicherungsbehältnis", ["text"] = "Eure Zauber und Fähigkeiten haben eine Chance, Euch in einen Blitzableiter zu verwandeln. Damit trefft Ihr 15 Sek. lang alle 3 Sek. ein zufälliges gegnerisches Ziel innerhalb von 40 Metern und fügt ihm ( 1 * 167 ) Naturschaden zu." }
entries[1233516] = { ["name"] = "K'arrocflinkschwinge", ["text"] = "Wirken in 1.5 sek.\nBeschwört dieses Reittier oder gibt es wieder frei.\n\"Ein Geschenk für geleistete Dienste. Dieser K'arroc hat schon einige gefährliche Flüge hinter sich.\"\nQuest:\nAuf nach Tazavesh, wieder einmal\nZone:\nK'aresh" }
entries[1233518] = { ["name"] = "Lavendelblauer K'arroc", ["text"] = "Wirken in 1.5 sek.\nBeschwört dieses Reittier oder gibt es wieder frei.\n\"Der vorherige Halter dieses besonders streitlustigen K'arroc starb während einer Untersuchung des ungebundenen Raums. Vielleicht akzeptiert er ja Euch... Oder vielleicht auch nicht.\"\nVerkäufer:\nShad'anis\nZone:\nK'aresh\nKosten:\n10" }
